#include "stdlib/blas/base/ssymv.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/blas/ext/base/sfill.h"
#include "stdlib/blas/base/sscal.h"
#include "stdlib/ndarray/base/assert/is_row_major.h"

/**
* Performs the matrix-vector operation `Y = α*A*X + β*Y` using alternative indexing semantics, where `α` and `β` are scalars, `X` and `Y` are `N` element vectors, and `A` is an `N` by `N` symmetric matrix supplied in packed form.
*
* @param uplo      specifies whether the upper or lower triangular part of the symmetric matrix `A` is supplied
* @param N         number of elements along each dimension of `A`
* @param alpha     scalar constant
* @param A         input matrix
* @param strideA1  stride of the first dimension of `A`
* @param strideA2  stride of the second dimension of `A`
* @param offsetA   starting index for `A`
* @param X         first input array
* @param strideX   `X` stride length
* @param offsetX   starting `X` index
* @param beta      scalar constant
* @param Y         second input array
* @param strideY   `Y` stride length
* @param offsetY   starting `Y` index
*/
void API_SUFFIX(c_ssymv_ndarray)( const CBLAS_UPLO uplo, const CBLAS_INT N, const float alpha, const float *A, const CBLAS_INT strideA1, const CBLAS_INT strideA2, const CBLAS_INT offsetA, const float *X, const CBLAS_INT strideX, const CBLAS_INT offsetX, const float beta, float *Y, const CBLAS_INT strideY, const CBLAS_INT offsetY ) {
	CBLAS_INT isrm;
	CBLAS_INT tmp2;
	CBLAS_INT tmp1;
	CBLAS_INT sa1;
	CBLAS_INT sa0;
	CBLAS_INT ix1;
	CBLAS_INT ix0;
	CBLAS_INT iy1;
	CBLAS_INT iy0;
	CBLAS_INT ix;
	CBLAS_INT i1;
	CBLAS_INT i0;
	CBLAS_INT oa;
	CBLAS_INT i;
	CBLAS_INT m;

	// Note on variable naming convention: sa#, ix#, i# where # corresponds to the loop number, with `0` being the innermost loop...

	int64_t strides[] = { strideA1, strideA2 };
	isrm = stdlib_ndarray_is_row_major( 2, strides );

	if ( isrm ) {
		sa0 = strideA2;
		sa1 = strideA1;
	} else {
		sa0 = strideA1;
		sa1 = strideA2;
	}
	// Y = beta*Y
	if ( beta != 1.0f ) {
		if ( beta == 0.0f ) {
			stdlib_strided_sfill_ndarray( N, 0.0f, Y, strideY, offsetY );
		} else {
			c_sscal_ndarray( N, beta, Y, strideY, offsetY );
		}
	}
	if ( N == 0 || ( alpha == 0.0f && beta == 1.0f ) ) {
		return;
	}
	// Form: Y = α*A*X + Y
	if (
		( !isrm && uplo == CblasUpper ) ||
		( isrm && uplo == CblasLower )
	) {
		ix1 = offsetX;
		iy1 = offsetY;
		for ( i1 = 0; i1 < N; i1++ ) {
			tmp1 = alpha * X[ ix1 ];
			tmp2 = 0.0f;
			ix0 = offsetX;
			iy0 = offsetY;
			oa = offsetA + (sa1*i1);
			for ( i0 = 0; i0 < i1; i0++ ) {
				Y[ iy0 ] += tmp1 * A[ oa+(sa0*i0) ];
				tmp2 += A[ oa+(sa0*i0) ] * X[ ix0 ];
				ix0 += strideX;
				iy0 += strideY;
			}
			Y[ iy1 ] += ( tmp1 * A[ oa+(sa0*i1) ] ) + ( alpha * tmp2 ); // eslint-disable-line max-len
			ix1 += strideX;
			iy1 += strideY;
		}
		return;
	}
	// ( !isrm && uplo === 'CblasLower' ) || ( isrm && uplo === 'CblasUpper' )
	ix1 = offsetX;
	iy1 = offsetY;
	for ( i1 = 0; i1 < N; i1++ ) {
		tmp1 = alpha * X[ ix1 ];
		tmp2 = 0.0f;
		oa = offsetA + (sa1*i1);
		Y[ iy1 ] += tmp1 * A[ oa+(sa0*i1) ];
		ix0 = ix1;
		iy0 = iy1;
		for ( i0 = i1+1; i0 < N; i0++ ) {
			ix0 += strideX;
			iy0 += strideY;
			Y[ iy0 ] += tmp1 * A[ oa+(sa0*i0) ];
			tmp2 += A[ oa+(sa0*i0) ] * X[ ix0 ];
		}
		Y[ iy1 ] += alpha * tmp2;
		ix1 += strideX;
		iy1 += strideY;
	}
	return Y;
}
